<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">JSON&#x5BF9;&#x6BD4;</text><text class="nav-icon"> </text></view></view><view class="content"><view class="editor-row"><view class="editor-col"><text class="editor-label">JSON A</text><textarea class="json-input" v-model="jsonA" placeholder="&#x8F93;&#x5165;JSON..." /><text class="error-text" v-if="errA">{{errA}}</text></view><view class="editor-col"><text class="editor-label">JSON B</text><textarea class="json-input" v-model="jsonB" placeholder="&#x8F93;&#x5165;JSON..." /><text class="error-text" v-if="errB">{{errB}}</text></view></view><view class="compare-btn" @click="compare"><text>&#x5BF9;&#x6BD4;</text></view><view v-if="diffResult" class="diff-result"><text class="diff-title">&#x5DEE;&#x5F02;&#x7ED3;&#x679C;</text><view class="diff-line" v-for="(line, idx) in diffResult" :key="idx" :class="line.type">{{ line.text }}</view></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const jsonA = ref("")
const jsonB = ref("")
const errA = ref("")
const errB = ref("")
const diffResult = ref(null)
function goBack() { uni.navigateBack() }
function compare() { errA.value = ""; errB.value = ""; var a, b; try { a = JSON.parse(jsonA.value) } catch(e) { errA.value = e.message; return } try { b = JSON.parse(jsonB.value) } catch(e) { errB.value = e.message; return } diffResult.value = diffObjects(a, b, "") }
function diffObjects(a, b, path) { var lines = []; var keys = Object.keys(Object.assign({}, a, b)).sort(); keys.forEach(function(k) { var p = path ? path+"."+k : k; if (!(k in a)) { lines.push({type:"added", text: "+ " + p + ": " + JSON.stringify(b[k])}) } else if (!(k in b)) { lines.push({type:"removed", text: "- " + p + ": " + JSON.stringify(a[k])}) } else if (typeof a[k] === "object" && typeof b[k] === "object" && a[k] !== null && b[k] !== null) { lines = lines.concat(diffObjects(a[k], b[k], p)) } else if (a[k] !== b[k]) { lines.push({type:"changed", text: "~ " + p + ": " + JSON.stringify(a[k]) + " \u2192 " + JSON.stringify(b[k]) }) } }); return lines.length ? lines : [{type:"same", text: "\u65E0\u5DEE\u5F02"}] }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#0891b2,#0e7490);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.editor-row{display:flex;gap:16rpx;margin-bottom:16rpx}.editor-col{flex:1}.editor-label{font-size:26rpx;color:#333;font-weight:600;display:block;margin-bottom:8rpx}.json-input{width:100%;height:400rpx;background:#fff;border-radius:12rpx;padding:16rpx;font-size:24rpx;font-family:monospace;border:2rpx solid #eee;box-sizing:border-box}.error-text{font-size:22rpx;color:#ef4444;margin-top:8rpx}.compare-btn{background:linear-gradient(135deg,#0891b2,#0e7490);border-radius:16rpx;padding:24rpx;text-align:center;margin-bottom:16rpx}.compare-btn text{font-size:30rpx;color:#fff;font-weight:600}.diff-result{background:#fff;border-radius:16rpx;padding:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.diff-title{font-size:28rpx;color:#333;font-weight:600;display:block;margin-bottom:16rpx}.diff-line{font-size:24rpx;font-family:monospace;padding:8rpx 12rpx;border-radius:8rpx;margin-bottom:4rpx}.diff-line.added{background:#d1fae5;color:#059669}.diff-line.removed{background:#fee2e2;color:#ef4444}.diff-line.changed{background:#fef3c7;color:#f59e0b}.diff-line.same{color:#999}</style>